O=[]
O.append(R(6419173,
en=("Curry Yogurt Marinated Tilapia","Here is an easy, affordable meal to try for dinner this week. Although it is simple to prepare, it is full of sweet and spicy flavor.","4",None,
["1 nonstick cooking spray","4 tilapia fillets","1 medium onion (halved and thinly sliced)","1 medium orange or yellow bell pepper (seeded and thinly sliced)","1 cup plain nonfat Greek yogurt","1 cup unsweetened coconut milk beverage","2 tablespoons sweet curry powder","1/2 teaspoon cayenne pepper","1 teaspoon paprika","1 teaspoon garlic powder","1/2 teaspoon salt","1/4 teaspoon black pepper"],
["Preheat oven to 375° F. Coat an 8x11-inch baking dish with cooking spray.","Place the four tilapia fillets side by side in the dish.","Top the fillets with the sliced onion and bell pepper.","In a medium bowl, mix all remaining ingredients and pour over the fish and vegetables.","Bake for 30 minutes. Let the fish rest for 15 minutes before serving. The vegetables should be slightly crisp and the fish should be fully cooked but tender."],[],[]),
ar=("سمك البلطي المتبّل بالزبادي والكاري","إليك وجبة سهلة واقتصادية يمكنك تجربتها على العشاء هذا الأسبوع. ورغم أنها بسيطة التحضير، فهي مليئة بالنكهة الحلوة الحارة.","4",None,
["1 بخاخ طهي غير لاصق","4 شرائح سمك بلطي","1 بصلة متوسطة (مقطوعة إلى نصفين وشرائح رفيعة)","1 فلفل رومي متوسط برتقالي أو أصفر (منزوع البذور ومقطّع إلى شرائح رفيعة)","1 كوب زبادي يوناني سادة خالي الدسم","1 كوب مشروب حليب جوز الهند غير المحلى","2 ملعقة كبيرة مسحوق كاري حلو","½ ملعقة صغيرة فلفل حار (كايين)","1 ملعقة صغيرة بابريكا","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الفرن مسبقًا إلى 375° فهرنهايت (190° مئوية). ادهن طبق خبز مقاس 8×11 بوصة ببخاخ الطهي.","ضع شرائح السمك الأربع جنبًا إلى جنب في الطبق.","غطِّ شرائح السمك بالبصل المقطّع والفلفل الرومي.","في وعاء متوسط، اخلط جميع المكونات المتبقية ثم اسكبها على السمك والخضار.","اخبزه لمدة 30 دقيقة. اترك السمك يرتاح لمدة 15 دقيقة قبل التقديم. يجب أن تكون الخضار مقرمشة قليلًا وأن يكون السمك مطهوًا جيدًا لكنه طري."],[],[])))
O.append(R(6419902,
es=("Untable de atún y aguacate","Este untable de atún y aguacate es una deliciosa combinación de atún rico en omega-3 y aguacate cremoso. Ya sea para cubrir galletas saladas, untar en pan tostado o acompañar verduras, este dúo de atún y aguacate es una forma deliciosa y apta para personas con diabetes de disfrutar un untable nutritivo y sabroso a la vez.","4","1/3 de taza de untable",
["1 lata (5 onzas) de atún en agua (escurrido)","1 aguacate mediano (machacado)","1/4 de taza de yogur griego natural sin grasa","2 cucharadas de jugo de limón","2 tallos de cebollín (cebolla verde) (picados finos)","1 tallo de apio (en cubos pequeños)","1/4 de cucharadita de ajo en polvo","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra"],
["En un tazón, combine el atún escurrido, el aguacate maduro machacado, el yogur griego natural, el jugo fresco de limón, el cebollín picado fino, el apio en cubos pequeños, el ajo en polvo, la sal y la pimienta. Revuelva hasta que los ingredientes estén bien mezclados, asegurándose de que el atún y el aguacate queden distribuidos de manera uniforme y la mezcla tenga una consistencia cremosa.","Pruebe el untable y ajuste el sazón, agregando más sal, pimienta o jugo de limón según su gusto."],[],[]),
ar=("دهن التونة والأفوكادو","هذا الدهن من التونة والأفوكادو مزيج لذيذ من التونة الغنية بأوميغا-3 والأفوكادو الكريمي. سواء استخدمته لتغطية البسكويت المملح أو دهنه على الخبز المحمص أو لتغميس الخضار، فإن ثنائي التونة والأفوكادو هذا طريقة لذيذة ومناسبة لمرضى السكري للاستمتاع بدهن مفيد وشهي في آنٍ واحد.","4","⅓ كوب من الدهن",
["1 علبة (5 أونصات) تونة معبأة في الماء (مصفاة)","1 حبة أفوكادو متوسطة (مهروسة)","¼ كوب زبادي يوناني سادة خالي الدسم","2 ملعقة كبيرة عصير ليمون","2 عود بصل أخضر (مفروم ناعمًا)","1 عود كرفس (مقطّع مكعبات صغيرة)","¼ ملعقة صغيرة مسحوق الثوم","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["في وعاء للخلط، اخلط التونة المصفاة والأفوكادو الناضج المهروس والزبادي اليوناني السادة وعصير الليمون الطازج والبصل الأخضر المفروم ناعمًا والكرفس المقطّع مكعبات صغيرة ومسحوق الثوم والملح والفلفل. قلّب المكونات حتى تمتزج جيدًا، مع التأكد من توزيع التونة والأفوكادو بالتساوي وأن يصبح قوام الخليط كريميًا.","تذوّق الدهن وعدّل التتبيلة بإضافة المزيد من الملح أو الفلفل أو عصير الليمون حسب ذوقك."],[],[])))
O.append(R(6420195,
es=("Tazón crujiente de yogur y moras sin gluten","Un refrigerio sin gluten con capas de yogur griego cremoso sin grasa, moras jugosas y granola crujiente sin gluten. Ofrece un equilibrio de proteína, fibra y un crujido satisfactorio, lo que lo convierte en una opción rápida y nutritiva para un impulso a media tarde o un desayuno ligero.","1","1 taza",
["3/4 de taza de yogur griego natural sin grasa","1/4 de taza de granola sin gluten","1/2 taza de moras"],
["Ponga con una cuchara 3/4 de taza de yogur griego sin grasa en un tazón pequeño.","Agregue 1/2 taza de moras sobre el yogur.","Espolvoree 1/4 de taza de granola sin gluten por encima.","Sirva de inmediato para que la granola se mantenga crujiente."],[],[]),
ar=("وعاء الزبادي بالتوت الأسود المقرمش (خالٍ من الغلوتين)","وجبة خفيفة خالية من الغلوتين تتكوّن من طبقات من الزبادي اليوناني الكريمي خالي الدسم والتوت الأسود الطري وغرانولا مقرمشة خالية من الغلوتين. توفر توازنًا بين البروتين والألياف وقرمشة مُرضية، مما يجعلها خيارًا سريعًا ومغذّيًا لدفعة طاقة في منتصف النهار أو فطورًا خفيفًا.","1","1 كوب",
["¾ كوب زبادي يوناني سادة خالي الدسم","¼ كوب غرانولا خالية من الغلوتين","½ كوب توت أسود"],
["ضع ¾ كوب من الزبادي اليوناني خالي الدسم بالملعقة في وعاء صغير.","أضف ½ كوب من التوت الأسود فوق الزبادي.","رش ¼ كوب من الغرانولا الخالية من الغلوتين في الأعلى.","قدّمه فورًا لتبقى الغرانولا مقرمشة."],[],[])))
O.append(R(6420755,
es=("Cazuela de desayuno de salmón y verduras de primavera","Esta cazuela de desayuno primaveral, llena de sabor, puede prepararse con salmón enlatado o es una excelente manera de aprovechar el salmón fresco que sobró. Si usa salmón enlatado, busque la opción con el menor contenido de sodio. Esta cazuela se puede preparar con anticipación y recalentar, por lo que es perfecta para un brunch.","6","1 porción de cazuela + 1 rebanada de pan tostado",
["1 rociada de aceite en aerosol antiadherente, 0.25 g","1 libra de espárragos (unos 16 tallos, recortados y cortados en trozos de 2 pulgadas)","1 1/2 tazas de chícharos (guisantes) frescos o congelados","2 tazas de brócoli (floretes, picados)","1/2 pimiento rojo mediano (en cubos)","2 latas de salmón enlatado (escurrido)","6 claras de huevo grandes (o 3/4 de taza de sustituto de huevo)","3 huevos grandes","3/4 de taza de requesón (reducido en grasa y reducido en sodio)","3 cucharadas de eneldo fresco (picado)","1/2 cucharadita de pimienta negra","2 cucharadas de jugo de limón","1/2 taza de queso mozzarella parcialmente descremado (rallado)","6 rebanadas de pan integral (tostado)"],
["Precaliente el horno a 350 grados F. Rocíe una fuente para hornear de 9x13 pulgadas con aceite en aerosol.","Coloque los espárragos, los chícharos y el brócoli en una cacerola mediana con aproximadamente 1 pulgada de agua. Tape, deje que hierva y cocine por unos 2 minutos, o hasta que las verduras estén de color verde brillante y apenas tiernas. Escúrralas y colóquelas en un tazón con agua con hielo para enfriarlas rápidamente. Una vez frías, escúrralas bien, mezcle con el pimiento rojo y extienda las verduras en la fuente preparada. Distribuya los trozos de salmón sobre las verduras.","En un tazón mediano, bata las claras y los huevos a velocidad media durante aproximadamente 1 minuto. La mezcla debe quedar ligeramente espumosa. Agregue el requesón, el eneldo, la pimienta negra y el jugo de limón, y bata a velocidad media por un minuto más para deshacer el queso y combinar.","Vierta la mezcla de huevo sobre las verduras y el salmón. Cubra con el queso mozzarella.","Hornee de 50 a 60 minutos, hasta que la mezcla de huevo esté firme y no quede líquido. Un cuchillo o palillo insertado debe salir limpio.","Corte en 6 porciones, decore con microvegetales frescos si lo desea y sirva con una rebanada de pan tostado."],[],[]),
ar=("طاجن الفطور بالسلمون وخضار الربيع","يمكن تحضير طاجن الفطور الربيعي المنعش هذا بالسلمون المعلّب، وهو أيضًا طريقة رائعة للاستفادة من السلمون الطازج المتبقي. إذا استخدمت السلمون المعلّب، فاختر النوع الأقل احتواءً على الصوديوم. يمكن تحضير هذا الطاجن مسبقًا وإعادة تسخينه، مما يجعله مثاليًا لوجبة البرانش.","6","1 قطعة من الطاجن + 1 شريحة خبز محمص",
["1 بخة من بخاخ طهي غير لاصق، 0.25 غرام","1 رطل هليون (حوالي 16 عودًا، مقلّم ومقطّع إلى قطع بطول 2 بوصة)","1½ كوب بازلاء طازجة أو مجمدة","2 كوب بروكلي (زهيرات، مفرومة)","½ حبة فلفل رومي أحمر متوسطة (مقطّعة مكعبات)","2 علبة سلمون معلّب (مصفى)","6 بياض بيض كبير (أو ¾ كوب بديل البيض)","3 بيضات كبيرة","¾ كوب جبن قريش (قليل الدسم وقليل الصوديوم)","3 ملعقة كبيرة شبت طازج (مفروم)","½ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة عصير ليمون","½ كوب جبن موزاريلا قليل الدسم (مبشور)","6 شريحة خبز حبوب كاملة (محمصة)"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175 درجة مئوية). رش طبق طاجن مقاس 9×13 بوصة ببخاخ الطهي.","ضع الهليون والبازلاء والبروكلي في قدر متوسط مع حوالي 1 بوصة من الماء. غطِّه واتركه حتى يغلي، ثم اطهه لمدة 2 دقيقة تقريبًا، أو حتى يصبح لون الخضار أخضر زاهيًا وطريًا قليلًا فقط. صفِّ الخضار وضعها في وعاء من الماء المثلج لتبرد بسرعة. بعد أن تبرد، صفِّها جيدًا واخلطها مع الفلفل الرومي الأحمر ثم وزّعها في الطبق المجهّز. وزّع قطع السلمون فوق الخضار.","في وعاء متوسط، اخفق بياض البيض والبيض الكامل على سرعة متوسطة لمدة 1 دقيقة تقريبًا. يجب أن يكون الخليط رغويًا قليلًا. أضف الجبن القريش والشبت والفلفل الأسود وعصير الليمون واخفق على سرعة متوسطة لدقيقة أخرى لتفتيت الجبن ودمج المكونات.","اسكب خليط البيض فوق الخضار والسلمون. غطِّه بجبن الموزاريلا.","اخبزه لمدة 50 إلى 60 دقيقة، حتى يتماسك خليط البيض ولا يتبقى أي سائل. يجب أن تخرج السكين أو عود الأسنان نظيفة عند غرزها.","قطّعه إلى 6 قطع، وزيّنه بالخضار الدقيقة الطازجة (ميكروجرينز) إن رغبت، وقدّمه مع شريحة من الخبز المحمص."],[],[])))
O.append(R(6421611,
es=("Hamburguesitas de salchicha para el desayuno, sin culpa","¡Se acabaron los días de renunciar a algunos de nuestros alimentos favoritos! Esta salchicha para el desayuno está llena de sabor gracias al pavo molido y a muchas especias. ¡El desayuno puede volver a ser su comida favorita del día!","14","2 hamburguesitas",
["2 libras de pavo molido magro","1 cucharadita de condimento para aves","1 cucharadita de semillas de hinojo","1/2 cucharadita de cebolla en polvo","1 cucharada de perejil fresco (picado)","1/4 de cucharadita de hojuelas de pimiento rojo triturado (opcional)","1/2 cucharadita de sal","1/4 de cucharadita de pimienta negra","1 cucharada de jarabe de arce"],
["Combine todos los ingredientes en un tazón grande y mezcle bien.","Divida la mezcla en 28 porciones y forme hamburguesitas de 2 pulgadas.","En una sartén grande a fuego medio-bajo, cocine las hamburguesitas de 3 a 5 minutos por lado, o hasta que ya no estén rosadas en el centro. Asegúrese de que alcancen una temperatura interna de 165° F. Sirva de inmediato."],[],[]),
ar=("أقراص سجق الفطور الخفيفة (بلا شعور بالذنب)","ولّت أيام التخلي عن بعض أطعمتنا المفضلة! سجق الفطور هذا مليء بالنكهة بفضل لحم الديك الرومي المفروم والكثير من التوابل. يمكن للفطور أن يصبح مجددًا وجبتك المفضلة خلال اليوم!","14","2 قرص",
["2 رطل لحم ديك رومي مفروم قليل الدهن","1 ملعقة صغيرة بهارات الدواجن","1 ملعقة صغيرة بذور الشمرة","½ ملعقة صغيرة مسحوق البصل","1 ملعقة كبيرة بقدونس طازج (مفروم)","¼ ملعقة صغيرة رقائق الفلفل الأحمر المجروش (اختياري)","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة شراب القيقب"],
["اخلط جميع المكونات جيدًا في وعاء كبير.","قسّم الخليط إلى 28 حصة وشكّله على هيئة أقراص بقطر 2 بوصة.","في مقلاة كبيرة على نار متوسطة إلى منخفضة، اطهِ الأقراص من 3 إلى 5 دقائق لكل جانب، أو حتى يختفي اللون الوردي من الوسط. تأكد من وصول درجة حرارتها الداخلية إلى 165° فهرنهايت (75° مئوية). قدّمها فورًا."],[],[])))
O.append(R(6421780,
ar=("لفائف الخضار المشوية","لتحضير هذه الوصفة بشكل أسرع، زر محل الأطعمة الجاهزة القريب منك واشترِ بعض الخضار المشوية الجاهزة!","4","1 لفافة",
["1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة خل بلسمي","¼ ملعقة صغيرة فلفل أسود","1 حبة كوسا متوسطة (مقطّعة طوليًا إلى 8 شرائح)","1 حبة قرع أصفر متوسطة (مقطّعة طوليًا إلى 8 شرائح)","1 حبة فلفل رومي أحمر متوسطة (مقطّعة إلى 4 شرائح)","4 خبز تورتيلا كبير من دقيق القمح الكامل (قليل الكربوهيدرات، بقطر 10 بوصة تقريبًا)","½ كوب حمص","8 أوراق ريحان طازج"],
["سخّن شواية داخلية أو خارجية.","في وعاء كبير، اخفق زيت الزيتون والخل البلسمي والفلفل الأسود المطحون معًا.","أضف شرائح الكوسا والقرع الأصفر والفلفل الرومي إلى التتبيلة واتركها لمدة 5 دقائق.","اشوِ الخضار نحو 2 إلى 3 دقائق على كل جانب.","افرد التورتيلا وادهنها بملعقتين كبيرتين من الحمص، ثم ضع ورقتي ريحان طازجتين وغطِّها بشريحتين من الكوسا وشريحتين من القرع الأصفر وشريحة واحدة من الفلفل الرومي.","اطوِ جانبي التورتيلا إلى الداخل ولفّها مثل البوريتو. يمكنك تقديمها فورًا أو لفّها جيدًا بالبلاستيك وحفظها في الثلاجة."],[],[])))
O.append(R(6422216,
es=("Pasta de verano con verduras","Este plato de pasta de verano con verduras usa espirales de calabacín para mantener los carbohidratos más bajos que una pasta tradicional. Esta deliciosa receta está llena de verduras como espárragos, brócoli y tomates, con una sabrosa salsa de limón. ¡Con solo un bocado, no creerá que la pasta es de calabacín!","4","1 taza",
["1 cucharada de aceite de oliva","12 onzas de tomates cherry (de preferencia amarillos)","4 dientes de ajo (picados)","8 onzas de espárragos (en trozos de 1 pulgada, sin los extremos duros)","8 onzas de brócoli (floretes)","12 onzas de fideos de calabacín (de la sección de congelados)","8 onzas de requesón (bajo en grasa)","2 cucharaditas de ralladura de limón","3 cucharadas de albahaca fresca (en tiras finas)","2 cucharadas de perejil fresco (picado fino)","1/4 de taza de jugo de limón"],
["Ponga a hervir una olla grande con agua.","Mientras tanto, caliente una sartén grande a fuego medio-alto y agregue el aceite de oliva. Cuando esté caliente, agregue los tomates.","Cocine hasta que los tomates empiecen a ampollarse y pierdan su forma (unos 5 minutos), moviendo la sartén de vez en cuando.","Baje el fuego a bajo y agregue el ajo. Cocine hasta que desprenda aroma (aproximadamente 1 minuto). Retire los tomates y el ajo del fuego y colóquelos en un tazón grande. Reserve la sartén para usarla después; no es necesario limpiarla todavía.","Cuando el agua hierva, agregue los espárragos y cocine por 1 minuto. Retírelos con un colador y agréguelos al tazón de verduras. Repita con el brócoli y los chícharos. Reserve el tazón de verduras.","Cocine el paquete de espirales de calabacín según las instrucciones del envase y reserve.","En otro tazón, mezcle el requesón, la ralladura de limón, la albahaca y el perejil.","Vuelva a calentar la sartén grande a fuego medio-alto. Agregue las verduras, los espirales de calabacín, la mezcla de requesón y el jugo de limón. Revuelva para combinar y cocine hasta que esté caliente y todo esté cubierto con la salsa de queso (unos 5 minutos)."],[],[]),
ar=("معكرونة الخضار الصيفية","يستخدم طبق المعكرونة الصيفي بالخضار هذا حلزونات الكوسا للحفاظ على كمية الكربوهيدرات أقل من المعكرونة التقليدية. وصفة لذيذة مليئة بالخضار مثل الهليون والبروكلي والطماطم، مع صلصة الليمون الشهية. من أول لقمة، لن تصدق أن المعكرونة مصنوعة من الكوسا!","4","1 كوب",
["1 ملعقة كبيرة زيت زيتون","12 أونصة طماطم كرزية (يفضّل الأصفر)","4 فص ثوم (مفروم)","8 أونصة هليون (قطع بطول 1 بوصة بعد إزالة الأطراف الخشبية)","8 أونصة بروكلي (زهيرات)","12 أونصة معكرونة كوسا (من قسم المجمدات)","8 أونصة جبن قريش (قليل الدسم)","2 ملعقة صغيرة قشر ليمون مبشور","3 ملعقة كبيرة ريحان طازج (مقطّع شرائح رفيعة)","2 ملعقة كبيرة بقدونس طازج (مفروم ناعمًا)","¼ كوب عصير ليمون"],
["اغلِ قدرًا كبيرًا من الماء.","في هذه الأثناء، ضع مقلاة كبيرة على نار متوسطة إلى عالية وأضف زيت الزيتون. عندما يسخن، أضف الطماطم.","اطهِ حتى تبدأ الطماطم بالانتفاخ وتفقد شكلها (حوالي 5 دقائق)، مع رج المقلاة من وقت لآخر.","اخفض النار إلى منخفضة وأضف الثوم. اطهِ حتى تفوح رائحته (حوالي 1 دقيقة). ارفع الطماطم والثوم عن النار وضعهما في وعاء كبير. ضع المقلاة جانبًا لاستخدامها لاحقًا، ولا حاجة لتنظيفها الآن.","عندما يغلي الماء، أضف الهليون واطهه لمدة 1 دقيقة. أخرجه بمصفاة وأضفه إلى وعاء الخضار. كرّر الأمر مع البروكلي والبازلاء. ضع وعاء الخضار جانبًا.","اطهِ عبوة حلزونات الكوسا حسب تعليمات الطهي وضعها جانبًا.","في وعاء منفصل، اخلط الجبن القريش وقشر الليمون والريحان والبقدونس.","أعد تسخين المقلاة الكبيرة على نار متوسطة إلى عالية. أضف الخضار وحلزونات الكوسا وخليط الجبن القريش وعصير الليمون. قلّب لدمج المكونات واطهِ حتى تسخن ويتغطى كل شيء بصلصة الجبن (حوالي 5 دقائق)."],[],[])))
O.append(R(6422262,
es=("Brócoli con sésamo y cebollín","Este brócoli con sésamo y cebollín es una guarnición rápida y sabrosa que resalta la textura crujiente natural del brócoli, con un toque asiático gracias al sésamo y el cebollín. Un complemento perfecto y apto para personas con diabetes para su comida.","4","1 taza",
["1 libra de brócoli (floretes)","2 cucharadas de aceite de sésamo","5 cucharaditas de salsa de soya baja en sodio","1 cucharada de vinagre de arroz","1 cucharada de semillas de sésamo (tostadas)","2 tallos de cebollín (en rodajas finas, partes blanca y verde)"],
["En una olla grande, ponga a hervir agua. Agregue los floretes de brócoli y escáldelos durante 2 minutos. Escurra y pase el brócoli a un tazón con agua con hielo para detener la cocción. Escurra de nuevo.","En una sartén grande u olla wok, caliente el aceite de sésamo a fuego medio-alto.","Agregue a la sartén el brócoli escaldado. Saltee de 2 a 3 minutos, hasta que el brócoli esté tierno pero crujiente.","En un tazón pequeño, bata la salsa de soya y el vinagre de arroz.","Vierta la mezcla de salsa de soya sobre el brócoli. Mezcle para cubrir de manera uniforme.","Siga cocinando por 2 minutos más para que los sabores se integren.","Retire el brócoli del fuego.","Espolvoree las semillas de sésamo tostadas y el cebollín sobre el brócoli. Mezcle con suavidad."],[],[]),
ar=("بروكلي بالسمسم والبصل الأخضر","هذه الوصفة من البروكلي بالسمسم والبصل الأخضر طبق جانبي سريع وشهي يُبرز قرمشة البروكلي الطبيعية بلمسة آسيوية من السمسم والبصل الأخضر. إضافة مثالية ومناسبة لمرضى السكري إلى وجبتك.","4","1 كوب",
["1 رطل بروكلي (زهيرات)","2 ملعقة كبيرة زيت سمسم","5 ملعقة صغيرة صلصة صويا قليلة الصوديوم","1 ملعقة كبيرة خل الأرز","1 ملعقة كبيرة بذور سمسم (محمصة)","2 عود بصل أخضر (مقطّع شرائح رفيعة، الجزء الأبيض والأخضر)"],
["في قدر كبير، اغلِ الماء. أضف زهيرات البروكلي وسلقها سلقًا سريعًا لمدة 2 دقيقة. صفِّها وانقل البروكلي إلى وعاء من الماء المثلج لوقف الطهي. صفِّه مرة أخرى.","في مقلاة كبيرة أو وعاء ووك، سخّن زيت السمسم على نار متوسطة إلى عالية.","أضف البروكلي المسلوق إلى المقلاة. قلّبه على النار لمدة 2 إلى 3 دقائق حتى يصبح طريًا ومقرمشًا.","في وعاء صغير، اخفق صلصة الصويا وخل الأرز معًا.","اسكب خليط الصويا فوق البروكلي. قلّبه حتى يتغطى بالتساوي.","واصل الطهي لمدة 2 دقيقة إضافية لتتداخل النكهات.","ارفع البروكلي عن النار.","رش بذور السمسم المحمصة والبصل الأخضر المقطّع فوق البروكلي. قلّبه برفق."],[],[])))
O.append(R(6422749,
es=("Tortitas de papa de coliflor con tomate asado y huevo","Estas torres de tortitas de coliflor son una alternativa ingeniosa y baja en carbohidratos al desayuno tradicional, con capas de tomates jugosos asados al horno y un huevo escalfado sedoso. La combinación de fibra, proteína y grasas saludables hace que esta comida sea saciante y adecuada para el nivel de glucosa en la sangre (azúcar en la sangre). Es una excelente opción para quienes controlan la diabetes y aun así desean un desayuno abundante y sabroso. Esta receta es baja en carbohidratos y vegetariana.","6","1 torre de tortita de coliflor",
["3 tazas de coliflor (1 cabeza mediana)","4 claras de huevo grandes","1/4 de taza de harina para todo uso","1/2 cucharadita de ajo en polvo","1/2 cucharadita de cebolla en polvo","1/2 cucharadita de sal kosher","1/2 cucharadita de pimienta negra","2 cucharaditas de aceite de oliva","1 tomate mediano (en rodajas de 1/4 de pulgada)","1/2 cucharadita de orégano seco","1 cucharada de vinagre blanco","6 huevos grandes","1 cucharada de perejil fresco (italiano, picado)"],
["Quite las hojas y el centro de la coliflor. Ralle con un rallador de caja o pulse en un procesador de alimentos hasta que parezca arroz. Coloque la coliflor rallada en un paño de cocina limpio y exprima el exceso de humedad.","En un tazón, mezcle la coliflor rallada, las claras de huevo, la harina, el ajo en polvo, la cebolla en polvo, la sal y la pimienta negra hasta que estén bien combinados. Forme 6 tortitas pequeñas.","Caliente el aceite de oliva en una sartén de hierro fundido o antiadherente a fuego medio. Coloque las tortitas en la sartén y aplánelas con el dorso de una espátula. Cocine las tortitas hasta que estén doradas y crujientes por ambos lados, unos 3 a 4 minutos por lado.","Encienda el horno en la función de asar (broil) a temperatura alta. Acomode las rodajas de tomate en una bandeja para hornear forrada. Unte con aceite de oliva y espolvoree con el orégano, la sal y la pimienta negra. Ase a temperatura alta de 3 a 5 minutos, hasta que estén suaves y ligeramente caramelizadas.","Llene una cacerola con 3 pulgadas de agua y deje que hierva a fuego lento. Agregue 1 cucharada de vinagre. Rompa cada huevo en un tazón pequeño y deslícelo con cuidado en el agua. Cocine de 3 a 4 minutos, hasta que las claras estén cuajadas pero las yemas sigan blandas. Retírelos con una espumadera y escúrralos sobre una toalla de papel.","Para servir, apile una tortita de coliflor, una rodaja de tomate asado y un huevo escalfado. Espolvoree con perejil."],[],[]),
ar=("بطاطس هاش براون القرنبيط مع الطماطم المشوية والبيض","أبراج هاش براون القرنبيط هذه بديل ذكي وقليل الكربوهيدرات لوجبات الفطور التقليدية، تتكون من طبقات من الطماطم المشوية العصيرة وبيضة مسلوقة بدون قشر بقوام حريري. يجعل مزيج الألياف والبروتين والدهون الصحية هذه الوجبة مشبعة ومناسبة لمستوى الجلوكوز في الدم (سكر الدم). وهي خيار ممتاز لمن يتحكمون في مرض السكري ويرغبون مع ذلك في فطور شهي ومشبع. هذه الوصفة قليلة الكربوهيدرات ونباتية.","6","1 برج هاش براون",
["3 كوب قرنبيط (رأس واحد متوسط)","4 بياض بيض كبير","¼ كوب دقيق متعدد الاستخدامات","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة ملح كوشر","½ ملعقة صغيرة فلفل أسود","2 ملعقة صغيرة زيت زيتون","1 حبة طماطم متوسطة (مقطّعة إلى دوائر بسمك ¼ بوصة)","½ ملعقة صغيرة أوريغانو مجفف","1 ملعقة كبيرة خل أبيض","6 بيضات كبيرة","1 ملعقة كبيرة بقدونس طازج (إيطالي، مفروم)"],
["انزع الأوراق والقلب من القرنبيط. اِبشره بمبشرة أو اخلطه بالنبض في محضّر الطعام حتى يشبه الأرز. ضع القرنبيط المبشور في منشفة مطبخ نظيفة واعصره للتخلص من الرطوبة الزائدة.","في وعاء، اخلط القرنبيط المبشور وبياض البيض والدقيق ومسحوق الثوم ومسحوق البصل والملح والفلفل الأسود حتى تتجانس المكونات جيدًا. شكّل الخليط على هيئة 6 أقراص صغيرة.","سخّن زيت الزيتون في مقلاة من الحديد الزهر أو غير لاصقة على نار متوسطة. ضع الأقراص في المقلاة واضغط عليها لتتسطح بظهر المقلب. اطهِ الأقراص حتى يصبح لونها ذهبيًا ومقرمشة من الجانبين، حوالي 3 إلى 4 دقائق لكل جانب.","شغّل الفرن على وضع الشواء (برويل) على درجة عالية. رتّب شرائح الطماطم على صينية خبز مبطنة. افرك بزيت الزيتون ورش الأوريغانو والملح والفلفل الأسود. اشوِ على درجة عالية من 3 إلى 5 دقائق حتى تلين وتتكرمل قليلًا.","املأ قدرًا بعمق 3 بوصات من الماء واتركه حتى يغلي على نار هادئة. أضف 1 ملعقة كبيرة من الخل. اكسر كل بيضة في وعاء صغير ثم أنزلها بحذر في الماء. اطهِ من 3 إلى 4 دقائق حتى يتماسك البياض وتبقى الصفار طرية. ارفعها بملعقة مثقبة وجفّفها على منديل ورقي.","للتقديم، ضع قرص هاش براون القرنبيط ثم شريحة طماطم مشوية ثم بيضة مسلوقة بدون قشر فوق بعضها. رش البقدونس."],[],[])))
O.append(R(6424125,
ar=("أسياخ لحم البقر بعشبة الليمون على الطريقة التايلندية","لتحضير مقبلات ممتعة أخرى بهذه الوصفة، أخرج اللحم المطهو من الأسياخ وقدّمه في أكواب من الخس مع رشة من الصلصة الحارة على الطريقة التايلندية.","12","1 سيخ",
["2 فص ثوم (مفروم)","1 ملعقة صغيرة فلفل أسود","2 رطل فيليه لحم بقري قليل الدهن (مقطّع إلى قطع بحجم 1 بوصة)","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","2 عود عشبة الليمون كاملة (مفرومة)","12 سيخ خيزران كامل","2 ملعقة صغيرة بديل سكر قليل السعرات","1 كوب ريحان (أو ريحان تايلندي، مفروم)","1 كوب كزبرة خضراء (مفرومة)","2 حبة ليمون أخضر متوسطة (مقطّعة إلى 6 أرباع لكل واحدة)"],
["انقع أسياخ الخيزران في ماء دافئ لمدة 30 دقيقة على الأقل.","في وعاء متوسط، اخفق المُحلّي قليل أو منعدم السعرات وصلصة الصويا والفلفل والثوم وعشبة الليمون. أضف اللحم إلى التتبيلة واتركه ليتبّل في الثلاجة لمدة ساعة واحدة على الأقل (وحتى أربع ساعات).","جهّز شواية داخلية أو خارجية.","أخرج اللحم من التتبيلة ووزّعه بالتساوي على الأسياخ الـ12. تخلّص من التتبيلة.","اشوِ الأسياخ نحو 5 دقائق لكل جانب.","زيّن الأسياخ بالريحان والكزبرة الخضراء وربع ليمونة."],[],[])))
O.append(R(6424759,
es=("Requesón sin grasa","Información nutricional del requesón sin grasa","1","1/2 taza",["1/2 taza de requesón sin grasa"],[],[],[]),
ar=("جبن قريش خالي الدسم","المعلومات الغذائية للجبن القريش خالي الدسم","1","½ كوب",["½ كوب جبن قريش خالي الدسم"],[],[],[])))
O.append(R(6425583,
es=("Quesadilla de champiñones y espinaca","La quesadilla de champiñones y espinaca es un plato delicioso y rápido de preparar que combina champiñones de sabor terroso, espinaca nutritiva y queso derretido entre tortillas. Es una excelente manera de comer más verduras y hasta a los niños les encantará.","8","1/2 quesadilla",
["1 cucharada de aceite de oliva","2 tazas de champiñones (de su elección) (en rodajas, como cremini o shiitake)","1 cebolla pequeña (en rodajas finas)","2 dientes de ajo (picados)","1/2 cucharadita de sal kosher","1/4 de cucharadita de pimienta negra","4 tazas de espinaca","8 tortillas pequeñas de harina integral","1 taza de queso mozzarella parcialmente descremado (rallado)","1/2 taza de queso mezcla mexicana (reducido en grasa, rallado)"],
["En una sartén grande, caliente el aceite de oliva a fuego medio. Agregue los champiñones en rodajas, la cebolla y el ajo picado. Saltee hasta que los champiñones estén dorados y la cebolla esté transparente, unos 5 a 7 minutos. Sazone con la sal kosher y la pimienta negra.","Agregue la espinaca fresca a la sartén y cocine hasta que se marchite, unos 2 a 3 minutos. Retire del fuego.","Coloque una tortilla en una sartén seca a fuego medio. Espolvoree una porción de ambos quesos sobre la mitad de la tortilla.","Ponga con una cuchara una porción generosa de la mezcla de champiñones y espinaca sobre el queso.","Doble la tortilla por la mitad para cubrir el relleno y presione con suavidad.","Cocine la quesadilla por ambos lados hasta que la tortilla esté crujiente y el queso se haya derretido, unos 2 a 3 minutos por lado.","Repita el proceso con el resto de las tortillas y el relleno.","Una vez cocidas, corte cada quesadilla en triángulos y sirva."],[],[]),
ar=("كيساديا الفطر والسبانخ","كيساديا الفطر والسبانخ طبق لذيذ وسريع التحضير يجمع بين الفطر ذي النكهة الترابية والسبانخ المغذية والجبن الذائب الممتد بين رقائق التورتيلا. إنها طريقة رائعة لتناول المزيد من الخضار، وحتى الأطفال سيستمتعون بها.","8","½ كيساديا",
["1 ملعقة كبيرة زيت زيتون","2 كوب فطر (من اختيارك) (مقطّع شرائح، مثل الكريميني أو الشيتاكي)","1 بصلة صغيرة (مقطّعة شرائح رفيعة)","2 فص ثوم (مفروم)","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود","4 كوب سبانخ","8 خبز تورتيلا صغير من دقيق القمح الكامل","1 كوب جبن موزاريلا قليل الدسم (مبشور)","½ كوب جبن مكسيكي مشكّل (قليل الدسم، مبشور)"],
["في مقلاة كبيرة، سخّن زيت الزيتون على نار متوسطة. أضف شرائح الفطر والبصل والثوم المفروم. قلّبها حتى يصبح الفطر بنيًا والبصل شفافًا، حوالي 5 إلى 7 دقائق. تبّلها بملح الكوشر والفلفل الأسود.","أضف السبانخ الطازجة إلى المقلاة واطهِها حتى تذبل، حوالي 2 إلى 3 دقائق. ارفعها عن النار.","ضع رغيف تورتيلا في مقلاة جافة على نار متوسطة. رش كمية من الجبنين على نصف التورتيلا.","ضع كمية وفيرة من خليط الفطر والسبانخ بالملعقة فوق الجبن.","اطوِ التورتيلا إلى نصفين لتغطية الحشوة واضغط عليها برفق.","اطهِ الكيساديا من الجانبين حتى تصبح التورتيلا مقرمشة ويذوب الجبن، حوالي 2 إلى 3 دقائق لكل جانب.","كرّر العملية مع بقية التورتيلا والحشوة.","بعد النضج، قطّع كل كيساديا إلى مثلثات وقدّمها."],[],[])))
